import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,b as l,k as u,l as d,n as f,o as p,p as m,t as h,v as g}from"./shared-C5BCElVa.js";import{t as _}from"./cloud-BBv7Rv1J.js";import{k as v}from"./index-D5bsO7MS.js";var y=e();function b({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{chip:e??`Глава 3 · Блок 9 · HTTP как договор`,title:`Адрес и метод запроса`,intro:`В Planner мы уже работали через CLI и разбирали, как отдельный клиент обращается к тому же приложению. Полная модель request нам знакома по прежней работе. Сейчас разложим её на две части, чтобы спокойно восстановить адрес обращения и его намерение перед тем, как добавить остальные данные.`,tags:[{icon:(0,y.jsx)(v,{size:14}),label:`от локального вызова к запросу`},{icon:(0,y.jsx)(_,{size:14}),label:`URL, path и method`}]}),(0,y.jsxs)(s,{number:`00`,title:`От знакомого Planner к частям запроса`,children:[(0,y.jsx)(o,{children:`Сначала вспомним, где заканчивается локальная команда и начинается отдельное обращение к приложению. Затем выделим в уже знакомом сообщении адресную часть и намерение.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Мы знаем локальный CLI Planner, роли клиента и сервера и уже встречали request как сообщение.`},{title:`Новый вопрос`,description:`Как отдельно понять, к какому месту API обращаются и какое намерение передаёт клиент?`},{title:`Результат`,description:`Мы выделим готовые method и path и вернём их в учебной паре, сохранив путь без изменений.`}]}),(0,y.jsx)(`p`,{children:`Это короткое восстановление и перенос знакомой модели в более простой контракт. В предыдущей работе роли участников привели нас к сообщению целиком; теперь сосредоточимся на двух его полях. Дальше мы добавим к ним заголовки и тело запроса, а получившуюся модель используем при чтении ответа. Код Planner, его CLI и локальные данные здесь не меняются.`})]}),(0,y.jsxs)(s,{number:`01`,title:`Вспоминаем участников обмена`,children:[(0,y.jsx)(o,{children:`В текущем Planner CLI запускает локальную команду в том же проекте. Отдельный браузер не вызывает Python-функцию напрямую: он обращается к работающему приложению сообщением.`}),(0,y.jsx)(`p`,{children:`В знакомой схеме клиент начинает обращение, сервер его принимает, а приложение применяет общие правила Planner. Клиентом может быть браузер, бот или другая программа. CLI вызывал код локально; браузер обращается к работающему приложению сообщением. Сейчас восстановим эту границу, не настраивая сервер.`}),(0,y.jsx)(m,{prompt:`Сопоставим участника с его ролью в знакомом сценарии Planner.`,pairs:[{left:`CLI Planner`,right:`Локально вызывает код проекта`},{left:`Браузер`,right:`Начинает HTTP-обращение`},{left:`Приложение Planner`,right:`Принимает запрос и применяет общие правила`}],explanation:`В этом сценарии CLI остаётся локальным входом. Браузер начинает отдельное обращение, а приложение принимает его и выполняет нужную работу.`}),(0,y.jsx)(`p`,{children:`Теперь можно читать, что именно клиент отправил. HTTP (Hypertext Transfer Protocol) задаёт правила обмена запросом и ответом. Здесь мы изучаем запись запроса как модель, не отправляя её по сети.`})]}),(0,y.jsxs)(s,{number:`02`,title:`URL выбирает сервис, path указывает внутри API`,children:[(0,y.jsx)(o,{children:`URL, Uniform Resource Locator, это адрес ресурса. В примере он помогает клиенту выбрать сервис и увидеть путь, по которому обращение направлено внутри этого сервиса.`}),(0,y.jsxs)(`p`,{children:[`Прочитаем готовую строку: `,(0,y.jsx)(`code`,{children:`http://localhost:8000/tasks/12`}),`. Схема `,(0,y.jsx)(`code`,{children:`http`}),` указывает правила обращения, `,(0,y.jsx)(`code`,{children:`localhost`}),` обозначает компьютер, на котором работает клиент, а `,(0,y.jsx)(`code`,{children:`8000`}),` является портом выбранного сервиса. После адреса сервиса идёт path, то есть путь API: `,(0,y.jsx)(`code`,{children:`/tasks/12`}),`. В этой модели мы не запускаем сервис, поэтому пример не доказывает, что по адресу сейчас есть работающий сервер.`]}),(0,y.jsx)(h,{caption:`Адрес сервиса и path внутри API`,orientation:`vertical`,children:(0,y.jsxs)(p,{label:`Читаем части URL сверху вниз`,orientation:`vertical`,children:[(0,y.jsxs)(d,{title:`Адрес сервиса`,shape:`process`,children:[(0,y.jsx)(`code`,{children:`http://localhost:8000`}),(0,y.jsx)(`p`,{children:`Схема, host и порт`})]}),(0,y.jsx)(f,{label:`после адреса идёт`}),(0,y.jsxs)(d,{title:`Path`,shape:`process`,children:[(0,y.jsx)(`code`,{children:`/tasks/12`}),(0,y.jsx)(`p`,{children:`Путь внутри API`})]})]})}),(0,y.jsx)(`p`,{children:`В офисном здании адрес помогает найти здание, а указатель внутри ведёт к кабинету. Так адрес сервиса приводит к API, а path указывает место внутри него. Это только аналогия: path не сообщает, существует ли задача; его значение задаёт карта обращений сервера.`}),(0,y.jsx)(t,{rows:[[`http`,`Схема обращения, по которой клиент выбирает правила связи.`],[`localhost:8000`,`Адрес сервиса и его порт в этом локальном примере.`],[`/tasks/12`,`Path внутри API, а не имя файла на диске.`],[`backend/data/tasks.json`,`Пример локального пути к файлу проекта.`]]}),(0,y.jsxs)(`p`,{children:[`Слово «путь» встречается и в адресе API, и в файловой системе, но отвечает на разные вопросы. Path передаётся серверу как часть URL. `,(0,y.jsx)(`code`,{children:`backend/data/tasks.json`}),` обозначает файл на компьютере, где выполняется проект; отдельный браузер не получает доступ к нему, просто написав такое имя. В практике path будет уже готовой строкой: нам не понадобится разбирать URL, искать запись или открывать файл.`]}),(0,y.jsx)(l,{question:`В URL http://localhost:8000/tasks/12 какая часть является path?`,options:[`/tasks/12`,`localhost:8000`,`backend/data/tasks.json`],correctIndex:0,explanation:`После адреса сервиса в URL идёт /tasks/12. localhost:8000 выбирает сервис, а backend/data/tasks.json относится к локальной файловой системе.`}),(0,y.jsx)(n,{code:`service_url = "http://localhost:8000"
path = "backend/data/tasks.json"`,question:`Для обращения к API какое значение перепутали с path?`,options:[`Путь к локальному файлу записан вместо пути API`,`Адрес сервиса обязательно должен быть именем файла`,`Порт 8000 должен стать частью имени задачи`],correctIndex:0,explanation:`backend/data/tasks.json указывает на файл рядом с кодом сервера. Для адреса API path записывается после адреса сервиса, например /tasks/12.`,fix:`service_url = "http://localhost:8000"
path = "/tasks/12"`})]}),(0,y.jsxs)(s,{number:`03`,title:`Method передаёт намерение отдельно от адреса`,children:[(0,y.jsx)(o,{children:`Метод HTTP, или method, сообщает, какое намерение клиент вкладывает в обращение. Path отвечает на другой вопрос: куда именно направлена просьба внутри API.`}),(0,y.jsxs)(`p`,{children:[`Возьмём один path и два готовых метода: `,(0,y.jsx)(`code`,{children:`GET /tasks`}),` и `,(0,y.jsx)(`code`,{children:`POST /tasks`}),`. Адресная часть одинакова, но это разные запросы, потому что отличается намерение. Сейчас нам достаточно заметить различие в записи. Подробный выбор и последствия методов мы разберём отдельно, поэтому здесь не составляем таблицу действий Planner.`]}),(0,y.jsx)(`p`,{children:`Вернёмся к офисному примеру. Path похож на адрес кабинета, а method на поле в бланке у входа: в одном случае мы просим показать сведения, в другом передаём новую просьбу. Это помогает не смешивать место и намерение. Но method не является названием Python-функции и не обещает успех: приложение ещё должно принять запрос и обработать его.`}),(0,y.jsx)(c,{statement:(0,y.jsxs)(y.Fragment,{children:[(0,y.jsx)(`code`,{children:`GET /tasks`}),` и `,(0,y.jsx)(`code`,{children:`POST /tasks`}),` имеют одинаковый path, значит это один request.`]}),isTrue:!1,explanation:`Path одинаковый, но method различается. Пара method/path описывает обращение целиком, поэтому здесь получаются разные запросы.`}),(0,y.jsx)(c,{statement:(0,y.jsxs)(y.Fragment,{children:[(0,y.jsx)(`code`,{children:`GET /tasks`}),` и `,(0,y.jsx)(`code`,{children:`GET /tasks/12`}),` могут иметь одинаковый method и разные path.`]}),isTrue:!0,explanation:`Method в обеих записях одинаковый, а path различается. Поэтому адрес нельзя восстановить только по method.`}),(0,y.jsx)(`p`,{children:`Один path сочетается с разными намерениями, а один method встречается с разными path. HTTP-запрос состоит из согласованных частей. В задаче method и path даны заранее, поэтому выбирать метод по описанию действия не нужно.`})]}),(0,y.jsxs)(s,{number:`04`,title:`Пара готовых значений остаётся данными`,children:[(0,y.jsx)(o,{children:`В следующем примере функция получает method и path как аргументы и возвращает короткую подпись. Мы уже знаем, что return передаёт значение вызывающей строке кода, а print только показывает его в терминале.`}),(0,y.jsx)(`p`,{children:`Посмотрим на независимую функцию подписи, не на решение редакторской задачи. Здесь f-строка соединяет два готовых значения для показа. Она не отправляет запрос и не превращает строку в URL. Сначала мы проследим передачу значений, затем отдельно соберём в практике более точный учебный результат.`}),(0,y.jsx)(g,{code:`def request_label(method, path):
    return f"{method} {path}"

path = "/tasks/8"
label = request_label("GET", path)
print(label)`,steps:[{line:3,note:`После этой строки во внешней функции есть готовый path. Пока в коде нет сетевого обращения.`,vars:{path:`"/tasks/8"`}},{line:4,note:`Перед вызовом path уже задан. В вызов передаются значения GET и /tasks/8.`,vars:{path:`"/tasks/8"`}},{line:1,note:`Внутри функции параметры получили method = GET и path = /tasks/8. return собирает из них строку подписи.`,vars:{method:`"GET"`,path:`"/tasks/8"`}},{line:4,note:`После возврата внешнее имя label хранит GET /tasks/8. Параметры функции уже не являются внешними именами.`,vars:{path:`"/tasks/8"`,label:`"GET /tasks/8"`}},{line:5,note:`print показывает подпись в локальном терминале. Это не HTTP-response и не подтверждение обработки сервером.`,vars:{path:`"/tasks/8"`,label:`"GET /tasks/8"`}}]}),(0,y.jsx)(`p`,{children:`Трассировка показывает path снаружи, параметры во время вызова и результат после возврата. Это разбор хода кода, не его запуск. Различие прежнее: return передаёт значение, print показывает его человеку.`}),(0,y.jsx)(r,{tone:`info`,children:`Строки method и path в учебной модели остаются обычными значениями Python. Их наличие в словаре не означает, что браузер отправил сообщение или что Planner уже создал HTTP API.`})]}),(0,y.jsxs)(s,{number:`05`,title:`Форматируем method, сохраняя path`,children:[(0,y.jsxs)(o,{children:[`В знакомой практике строковый метод можно привести к верхнему регистру через `,(0,y.jsx)(`code`,{children:`.upper()`}),`. Этот метод строки возвращает новое значение, а не меняет исходную строку на месте.`]}),(0,y.jsx)(`p`,{children:`Для нашего контракта нормализуется только method. Path уже передан в нужной форме и возвращается без изменений, включая начальный слеш и все символы после него. Это задание проверяет точную учебную запись, а не разбирает произвольный URL и не выбирает операцию по смыслу.`}),(0,y.jsx)(t,{rows:[[`method`,`Получаем готовую строку и приводим её к верхнему регистру.`],[`path`,`Получаем готовую строку и сохраняем её посимвольно.`],[`return`,`Передаём словарь с ровно двумя ключами, ничего не печатаем.`]]}),(0,y.jsxs)(`p`,{children:[`Если переданный method записан как `,(0,y.jsx)(`code`,{children:`post`}),`, результатом этой операции будет новая строка `,(0,y.jsx)(`code`,{children:`POST`}),`. Входное значение остаётся прежним. Path не преобразуем: у функции нет задачи исправлять его, менять регистр или проверять существование ресурса. В коде дальше эти границы будут явно проверены на нескольких парах значений.`]}),(0,y.jsx)(`p`,{children:`Путь к файлу и path API остаются разными данными. Готовая пара method/path станет основой следующего шага: добавим headers и body. Поля задачи, статусы ответа и серверные операции в эту модель не входят.`})]}),(0,y.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(`p`,{children:`В редакторе проверим отдельную часть знакомого request. Практика исследовательская и автопроверяемая: сетевую библиотеку подключать и проект Planner менять не потребуется.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Распознаем пару`,description:`На готовых примерах отделим адрес сервиса и path, затем назовём method без выбора по действию.`},{title:`Вернём учебную запись`,description:`Соберём словарь ровно с method и path, преобразуем только method и сохраним path.`},{title:`Проверим другие входы`,description:`Повторим функцию с get, post и patch и разными path, проверив отсутствие вывода и изменения входов.`}]}),(0,y.jsx)(`p`,{children:`Общий результат упражнения покажет, что мы можем восстановить точную пару на новых строках. Автопроверка подтвердит контракт функции, а короткое устное объяснение закрепит разницу между методом, адресом API и локальным файлом.`}),(0,y.jsx)(`p`,{children:`В следующей карточке method и path будут уже подготовлены в заготовке, потому что платформа не переносит решение между редакторскими задачами. Там мы добавим headers и body, включая разницу между отсутствующим телом и пустым объектом. После этого полная модель request станет опорой для разбора response.`})]})]})}export{b as Lesson41};